"""Policy tests generated by MedGuard. Model-suggested tests are never written here."""

from __future__ import annotations

import json
from pathlib import Path

from app.policies import load_synthetic_patients

PLAN = [
    {
        "id": "test_pol01_unauthorized_patient_read",
        "policy_id": "POL-01",
        "title": "Unauthorized patient record access",
        "mandatory": True,
    },
    {
        "id": "test_pol02_cross_clinic_exposure",
        "policy_id": "POL-02",
        "title": "Cross-clinic data exposure",
        "mandatory": True,
    },
    {
        "id": "test_pol03_authentication_required",
        "policy_id": "POL-03",
        "title": "Missing authentication",
        "mandatory": True,
    },
    {
        "id": "test_pol04_clinician_role_required",
        "policy_id": "POL-04",
        "title": "Missing authorization",
        "mandatory": True,
    },
    {
        "id": "test_pol05_no_hardcoded_credentials",
        "policy_id": "POL-05",
        "title": "Hardcoded credentials",
        "mandatory": True,
    },
    {
        "id": "test_pol06_logs_exclude_sensitive_values",
        "policy_id": "POL-06",
        "title": "Sensitive information in application logs",
        "mandatory": True,
    },
    {
        "id": "test_pol07_no_string_built_sql",
        "policy_id": "POL-07",
        "title": "Unsafe database queries",
        "mandatory": True,
    },
    {
        "id": "test_pol08_invalid_patient_id_rejected",
        "policy_id": "POL-08",
        "title": "Missing input validation",
        "mandatory": True,
    },
    {
        "id": "test_req_authorized_own_clinic_read",
        "policy_id": "REQ-ALLOW",
        "title": "Authorized clinician reads own-clinic record",
        "mandatory": True,
    },
]

_TEMPLATE = Path(__file__).with_name("policy_test_template.py")


def generate_tests() -> dict:
    patients = load_synthetic_patients()
    own = patients["patients"][0]
    other = patients["patients"][1]
    source = _TEMPLATE.read_text(encoding="utf-8")
    replacements = {
        "__OWN_ID__": json.dumps(own["patient_id"]),
        "__OWN_CLINIC__": json.dumps(own["clinic_id"]),
        "__OTHER_ID__": json.dumps(other["patient_id"]),
        "__OTHER_CLINIC__": json.dumps(other["clinic_id"]),
        "__FORBIDDEN_LOGS__": json.dumps(patients["forbidden_in_logs"]),
        "__FORBIDDEN_LITERALS__": json.dumps(patients["forbidden_literals"]),
    }
    for key, value in replacements.items():
        source = source.replace(key, value)
    return {"source": source, "plan": [dict(item) for item in PLAN]}
